"""本地业务页面交互。"""

def detail_fragment(item):
    return "<input id=\"address\" list=\"areas\"><datalist id=\"areas\"><option value=\"桐花苑 1 栋\"><option value=\"桐花苑 2 栋\"></datalist><button id=\"address-check\">查询上门范围</button><output id=\"address-result\"></output><output id=\"provider\"></output><script>let address=document.querySelector('#address');let service=document.querySelector('#address-result');let time=document.querySelector('#result');address.oninput=()=>{service.textContent='';time.textContent='';document.querySelector('#provider').textContent=''};document.querySelector('#address-check').onclick=()=>{let a=address.value;if(a==='桐花苑 1 栋'){service.textContent='桐花苑 1 栋：服务区';document.querySelector('#provider').textContent='城区维修队'}else if(a==='桐花苑 2 栋'){service.textContent='桐花苑 2 栋：限制预约';document.querySelector('#provider').textContent='东区维修队'}else service.textContent='地址未确认'};document.querySelector('#preview').onclick=()=>time.textContent=service.textContent.includes('服务区')?'周二上门':'暂不可确认';</script>"
